mapper.select:
SELECT id, app_name, name, type, git_branch, commit_id, env,
       build_time, build_user, pipeline_run_id, pipeline_run_name,
       artifact_repository, artifact_repository_path, artifact_url,
       size, sha256, create_time, update_time
FROM artifact
WHERE deleted = 0

    AND app_name LIKE CONCAT('%', #{appName}, '%')


    AND name LIKE CONCAT('%', #{name}, '%')


    AND git_branch = #{gitBranch}


    AND env = #{env}


    AND type = #{type}


    ORDER BY ${sortField} ${sortOrder}
